# The emitted object keeps the input's addresses, so relinking it moves every
# symbol to the address this map gives.
---
triple:          'x86_64-apple-darwin'
binary-path:     '@OBJ@'
objects:
  - filename: '@OBJ@'
    symbols:
      - { sym: _g_func,  objAddr: 0x0,  binAddr: 0x5000, size: 0x30 }
      - { sym: _g_other, objAddr: 0x30, binAddr: 0x6000, size: 0x10 }
      - { sym: _g_var,   objAddr: 0x40, binAddr: 0x7000, size: 0x10 }
      - { sym: _s_var,   objAddr: 0x50, binAddr: 0x8000, size: 0x4 }
...
